const token   = 'REPLACE_WITH_SHOPIFY_ACCESS_TOKEN';
const baseUrl = 'https://zgqk4e-1m.myshopify.com/admin/api/2025-01/products.json';

let allProducts = [];
let pageInfo    = null;
let hasMore     = true;

while (hasMore) {
  let url = `${baseUrl}?fields=title,handle,variants&limit=250`;
  if (pageInfo) url += `&page_info=${pageInfo}`;

  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: url,
    headers: { 'X-Shopify-Access-Token': token },
    returnFullResponse: true
  });

  allProducts = allProducts.concat(response.body.products || []);

  const linkHeader = response.headers['link'] || '';
  const nextMatch  = linkHeader.match(/<([^>]+)>;\s*rel="next"/);
  if (nextMatch) {
    const pageInfoMatch = nextMatch[1].match(/page_info=([^&]+)/);
    pageInfo = pageInfoMatch ? pageInfoMatch[1] : null;
    hasMore  = !!pageInfo;
  } else {
    hasMore = false;
  }
}

return [{ json: { products: allProducts, totalFetched: allProducts.length } }];

const raw = $input.first().json;
const products = Array.isArray(raw.products) ? raw.products : [];

const lowStock = [];

for (const product of products) {
  const variants = Array.isArray(product.variants) ? product.variants : [];
  for (const variant of variants) {
    const qty = variant.inventory_quantity ?? 0;
    if (qty <= 0) {
      const variantLabel = variant.title && variant.title !== 'Default Title' ? variant.title : '';
      lowStock.push({
        title:   product.title + (variantLabel ? ` — ${variantLabel}` : ''),
        handle:  product.handle,
        stock:   qty,
        adminUrl: `https://zgqk4e-1m.myshopify.com/admin/products/${variant.product_id}`
      });
    }
  }
}

// Sort: out of stock (0) first, then negative
lowStock.sort((a, b) => a.stock - b.stock);

const today = new Date().toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' });

// Build HTML report
const rows = lowStock.map(p => {
  const stockLabel = p.stock === 0 ? 'Out of Stock' : `${p.stock}`;
  const stockColor = p.stock === 0 ? '#e63946' : '#ff6b35';
  return `<tr>
    <td style="padding:10px 14px;border-bottom:1px solid #eee;font-size:14px;color:#1a1a2e;">
      <a href="${p.adminUrl}" style="color:#1a1a2e;text-decoration:none;font-weight:600;">${p.title}</a>
    </td>
    <td style="padding:10px 14px;border-bottom:1px solid #eee;text-align:center;">
      <span style="background:${stockColor};color:#fff;font-size:12px;font-weight:700;padding:3px 10px;border-radius:20px;">${stockLabel}</span>
    </td>
  </tr>`;
}).join('');

const html = `<!DOCTYPE html>
<html lang="en">
<head><meta charset="UTF-8"/>
<style>
  body{font-family:Arial,sans-serif;background:#f4f4f4;margin:0;padding:0;}
  .wrapper{max-width:680px;margin:32px auto;background:#fff;border-radius:10px;overflow:hidden;box-shadow:0 2px 16px rgba(0,0,0,0.10);}
  .header{background:#1a1a2e;padding:24px 40px;display:flex;align-items:center;justify-content:space-between;}
  .header img{height:44px;object-fit:contain;}
  .header-right{text-align:right;color:#aaa;font-size:12px;}
  .header-right strong{color:#F5B800;font-size:16px;display:block;}
  .body{padding:32px 40px;}
  .summary{display:flex;gap:16px;margin-bottom:28px;}
  .summary-box{flex:1;background:#f9f7f2;border-radius:8px;padding:16px;text-align:center;}
  .summary-box .num{font-size:28px;font-weight:700;color:#e63946;}
  .summary-box .label{font-size:12px;color:#888;margin-top:4px;}
  table{width:100%;border-collapse:collapse;font-size:14px;}
  thead tr{background:#1a1a2e;color:#fff;}
  thead th{padding:11px 14px;text-align:left;font-weight:600;font-size:13px;}
  tbody tr:nth-child(even){background:#f9f7f2;}
  .footer{background:#f5f0e8;padding:16px 40px;text-align:center;font-size:11px;color:#888;border-top:1px solid #e5e0d8;}
</style>
</head>
<body>
<div class="wrapper">
  <div class="header">
    <img src="https://yellowfeather.netlify.app/logo-landscape.png" alt="Yellow Feather Books"/>
    <div class="header-right"><strong>Low Stock Report</strong>${today}</div>
  </div>
  <div class="body">
    <div class="summary">
      <div class="summary-box"><div class="num">${lowStock.length}</div><div class="label">Products Need Restocking</div></div>
      <div class="summary-box"><div class="num" style="color:#ff6b35;">${lowStock.filter(p => p.stock === 0).length}</div><div class="label">Completely Out of Stock</div></div>
    </div>
    ${lowStock.length === 0
      ? '<p style="color:#555;font-size:15px;">All products are well stocked. No action needed today.</p>'
      : `<table>
          <thead><tr><th>Product</th><th style="text-align:center;">Stock</th></tr></thead>
          <tbody>${rows}</tbody>
        </table>`
    }
  </div>
  <div class="footer">Yellow Feather Books &nbsp;·&nbsp; Automated daily report &nbsp;·&nbsp; 8:00 AM IST</div>
</div>
</body></html>`;

return [{ json: { html, totalLowStock: lowStock.length, today } }];
